function stop(){keys.clear();working=false;path=[];autoAction=null;s.player.vx=s.player.vz=0;orbit=false;pointerDown=null;mini.left=mini.right=false;}
function changed(){if(lastStage!==s.stage){working=false;path=[];autoAction=null;keys.clear();toast(['','Space to breathe. Broom unlocked.','Found a brass token. Keep it for the first game.','A clean foundation. Floor finishes unlocked.','The floor is yours. Pick a wall color.','A little color goes a long way.','It lives! Bring Star Signal back to the room.','The first light is on. Welcome back.'][s.stage]);tone(400+s.stage*80);lastStage=s.stage;}refresh();save();}
