const markerButtons=[];
function updateMarkers(){
  const items=[];
  if(s.held>=0){const b=M.bays[s.held];items.push({name:s.stage===6?'Place on restored floor':'Park in storage',x:s.stage===6?0:b.x,z:s.stage===6?2:-7.8,y:.4,fn:()=>navigate(s.stage===6?0:b.x,s.stage===6?2:-7.8,'park')});}
  else if(s.stage===0||s.stage>=5){s.cabinets.forEach((c,i)=>{if((s.stage===0&&!c.stored)||(s.stage>=5&&i===0))items.push({name:['Star Signal','Moon Rally','Pixel Garden'][i],x:c.x,z:c.z,y:2.8,fn:()=>{if(M.nearest(s)===i)interact();else navigate(c.x,c.z+1.75,i);}});});}
  while(markerButtons.length<items.length){const b=button('',()=>{});$('markers').append(b);markerButtons.push(b);}
  markerButtons.forEach((b,i)=>{const item=items[i];b.hidden=!item;if(!item)return;const p=new THREE.Vector3(item.x,item.y,item.z).project(camera);b.hidden=p.z>1;b.textContent=item.name;b.onclick=item.fn;b.style.left=(p.x*.5+.5)*innerWidth+'px';b.style.top=(-p.y*.5+.5)*innerHeight+'px';});
}
let statFrames=0,statTime=performance.now();
let stalled=0;
